public static WildcardType subtypeOf(Type bound) {
    // Handle nested wildcards to prevent infinite recursion
    if (bound instanceof WildcardType) {
        WildcardType wildcard = (WildcardType) bound;
        Type[] upperBounds = wildcard.getUpperBounds();
        if (upperBounds.length > 0 && !Object.class.equals(upperBounds[0])) {
            return wildcard; // Already a ? extends type
        }
        Type[] lowerBounds = wildcard.getLowerBounds();
        if (lowerBounds.length > 0) {
            return new WildcardTypeImpl(new Type[] { Object.class }, EMPTY_TYPE_ARRAY);
        }
    }
    return new WildcardTypeImpl(new Type[] { bound }, EMPTY_TYPE_ARRAY);
}
