```java
public double cumulativeProbability(double x) throws MathException {
    if (Double.isInfinite(x)) {
        if (x < 0) {
            return 0.0;
        } else {
            return 1.0;
        }
    }

    double z = (x - mean) / (standardDeviation * Math.sqrt(2.0));
    if (z < -20) {
        return 0.0;
    }
    if (z > 20) {
        return 1.0;
    }

    try {
        return 0.5 * (1.0 + Erf.erf(z));
    } catch (MaxIterationsExceededException e) {
        if (z < 0) {
            return 0.0;
        } else {
            return 1.0;
        }
    }
}
