```java
public double toDouble() {
    if (isInfinite()) {
        if (lessThan(getZero())) {
            return Double.NEGATIVE_INFINITY;
        } else {
            return Double.POSITIVE_INFINITY;
        }
    }

    if (isNaN()) {
        return Double.NaN;
    }

    Dfp y = this;
    boolean negate = false;
    if (lessThan(getZero())) {
        y = negate();
        negate = true;
    }

    // Handle zero case explicitly
    if (y.equals(getZero())) {
        return negate ? -0.0 : 0.0;
    }

    /* Find the exponent, first estimate by integer log10, then adjust */
    int exponent = (int)(y.log10() * 3.32);
    if (exponent < 0) {
        exponent--;
    }

    Dfp tempDfp = DfpMath.pow(getTwo(), exponent);
    while (tempDfp.lessThan(y) || tempDfp.equals(y)) {
        tempDfp = tempDfp.multiply(2);
        exponent++;
    }
    exponent--;

    /* We have the exponent, now work on the mantissa */
    y = y.divide(DfpMath.pow(getTwo(), exponent));
    if (exponent > -1023) {
        y = y.subtract(getOne());
    }

    if (exponent < -1074) {
        return negate ? -0.0 : 0.0;
    }

    if (exponent > 1023) {
        return negate ? Double.NEGATIVE_INFINITY : Double.POSITIVE_INFINITY;
    }

    y = y.multiply(newInstance(4503599627370496l)).rint();
    String str = y.toString();
    str = str.substring(0, str.length()-1);
    long mantissa = Long.parseLong(str);

    if (mantissa == 4503599627370496L) {
        mantissa = 0;
        exponent++;
    }

    /* Its going to be subnormal, so make adjustments */
    if (exponent <= -1023) {
        exponent--;
    }

    while (exponent < -1023) {
        exponent++;
        mantissa >>>= 1;
    }

    long bits = mantissa | ((exponent + 1023L) << 52);
    double x = Double.longBitsToDouble(bits);

    if (negate) {
        x = -x;
    }

    return x;
}
