@Override
      public boolean apply(Node n) {
        // When the node is null it means, we reached the implicit return
        // where the function returns (possibly without an return statement)
        if (n == null) {
          return false;
        }

        // Check for calls that may have side effects and reference dependent variables
        if (n.isCall() && NodeUtil.functionCallHasSideEffects(n)) {
          Node firstArg = n.getFirstChild().getNext();
          while (firstArg != null) {
            if (NodeUtil.isReferenceToDependentVariable(firstArg, dependentVars)) {
              return true;
            }
            firstArg = firstArg.getNext();
          }
        }

        if (n.isNew() && NodeUtil.constructorCallHasSideEffects(n)) {
          Node firstArg = n.getFirstChild().getNext();
          while (firstArg != null) {
            if (NodeUtil.isReferenceToDependentVariable(firstArg, dependentVars)) {
              return true;
            }
            firstArg = firstArg.getNext();
          }
        }

        for (Node c = n.getFirstChild(); c != null; c = c.getNext()) {
          if (!ControlFlowGraph.isEnteringNewCfgNode(c) && apply(c)) {
            return true;
          }
        }
        return false;
      }
