```java
private boolean isVariableStillLiveWithinExpression(
      Node n, Node exprRoot, String variable) {
    while (n != exprRoot) {
      VariableLiveness state = VariableLiveness.MAYBE_LIVE;
      switch (n.getParent().getType()) {
        case Token.OR:
        case Token.AND:
          // If the current node is the first child of AND/OR,
          // check the second operand
          if (n == n.getParent().getFirstChild()) {
            state = isVariableReadBeforeKill(n.getParent().getLastChild(), variable);
          }
          break;

        case Token.HOOK:
          // If current node is the condition, check both branches
          if (n == n.getParent().getFirstChild()) {
            Node thenBranch = n.getNext();
            Node elseBranch = n.getParent().getLastChild();
            VariableLiveness thenState = isVariableReadBeforeKill(thenBranch, variable);
            if (thenState == VariableLiveness.READ) {
              return true;
            }
            VariableLiveness elseState = isVariableReadBeforeKill(elseBranch, variable);
            if (elseState == VariableLiveness.READ) {
              return true;
            }
            if (thenState == VariableLiveness.KILL || elseState == VariableLiveness.KILL) {
              return false;
            }
          }
          break;

        default:
          for(Node sibling = n.getNext(); sibling != null;
              sibling = sibling.getNext()) {
            if (!ControlFlowGraph.isEnteringNewCfgNode(sibling)) {
              state = isVariableReadBeforeKill(sibling, variable);
              // If we see a READ or KILL there is no need to continue.
              if (state == VariableLiveness.READ) {
                return true;
              } else if (state == VariableLiveness.KILL) {
                return false;
              }
            }
          }
      }
      n = n.getParent();
    }
    return false;
  }
