private final int _outputRawMultiByteChar(int ch, char[] cbuf, int inputOffset, int inputEnd)
        throws IOException
    {
        // Let's handle surrogates gracefully (as 4 byte output):
        if (ch >= SURR1_FIRST && ch <= SURR1_LAST) { // first part?
            // Do we have second part?
            if (inputOffset >= inputEnd || cbuf == null) { // nope... have to note down
                _reportError("Split surrogate on writeRaw() input (last character)");
                return inputOffset;
            }
            _outputSurrogates(ch, cbuf[inputOffset]);
            return inputOffset+1;
        }
        if (ch >= SURR2_FIRST && ch <= SURR2_LAST) { // second part without first?
            _reportError("Split surrogate on writeRaw() input (first character missing)");
            return inputOffset;
        }
        final byte[] bbuf = _outputBuffer;
        bbuf[_outputTail++] = (byte) (0xe0 | (ch >> 12));
        bbuf[_outputTail++] = (byte) (0x80 | ((ch >> 6) & 0x3f));
        bbuf[_outputTail++] = (byte) (0x80 | (ch & 0x3f));
        return inputOffset;
    }
