@Override
    public void writeRaw(String text, int offset, int len) throws IOException
    {
        final char[] buf = _charBuffer;
        final int bufLen = buf.length;

        while (len > 0) {
            int len2 = Math.min(bufLen, len);
            text.getChars(offset, offset+len2, buf, 0);
            // Check if last character is first part of surrogate pair
            if (len2 < len && len2 > 0) {
                char c = buf[len2-1];
                if (c >= SURR1_FIRST && c <= SURR1_LAST) {
                    // If so, don't write it yet - wait for the pair
                    len2--;
                }
            }
            writeRaw(buf, 0, len2);
            offset += len2;
            len -= len2;
        }
    }
